        platform="cpu",
        pass_owned_tensor=True,
    )

    x = jnp.arange(10, device=jax.devices("cpu")[0], dtype=jnp.float32)

    result = jax.ffi.ffi_call(
        "owned_tensor_no_leak",
        jax.ShapeDtypeStruct(x.shape, x.dtype),
